 'use strict';
window.ThingsProviderBridge=(()=>{
 const pending=new Map();
 function call(value){if(window.ThingsBookDesktop?.providerRequest)return window.ThingsBookDesktop.providerRequest(value);if(!window.ThingsBookAndroid?.providerRequest)return Promise.reject(Error('Use the Windows or Android app to connect this provider.'));return new Promise((resolve,reject)=>{const id=crypto.randomUUID(),timer=setTimeout(()=>{pending.delete(id);window.ThingsBookAndroid.cancelProvider();reject(Error('Provider request timed out.'));},60000);pending.set(id,{resolve,reject,timer});window.ThingsBookAndroid.providerRequest(id,JSON.stringify(value));});}
 function cancel(){window.ThingsBookDesktop?.cancelProvider?.();window.ThingsBookAndroid?.cancelProvider?.();for(const p of pending.values()){clearTimeout(p.timer);p.reject(Error('Request cancelled.'));}pending.clear();}
 function receive(id,text){const p=pending.get(id);if(!p)return;pending.delete(id);clearTimeout(p.timer);try{const r=JSON.parse(text);if(r.error)p.reject(Error(r.error));else p.resolve(r.value);}catch{p.reject(Error('Invalid provider response.'));}}
 return {call,cancel,receive};
})();
window.ThingsProviders=(()=>{
 const q=id=>document.getElementById(id),bridge=ThingsProviderBridge,dialog=el('dialog','sanctuary-dialog discovery-dialog');dialog.id='zlibrary-dialog';
 const heading=el('div','dialog-heading'),close=el('button','secondary','Close');close.type='button';close.onclick=()=>clear();heading.append(el('h2','','Z-Library'),close);
 const help=el('p','fine','Connect your own account at https://z-lib.gd. Searches and selected downloads contact this provider; your private books, reading history and voices stay on this device. Account availability and download limits apply. Sessions are protected on this device and excluded from book backups.'),connection=el('p','fine'),consentLabel=el('label','catalog-consent'),consent=el('input');consent.type='checkbox';consentLabel.append(consent,document.createTextNode(' Allow provider connections for this visit'));
 const login=el('form','provider-login'),email=el('input'),password=el('input'),signin=el('button','primary','Sign in on this device'),disconnect=el('button','secondary','Disconnect this device');email.type='email';email.maxLength=254;email.autocomplete='username';email.placeholder='Provider account email';email.setAttribute('aria-label','Z-Library account email');password.type='password';password.maxLength=4096;password.autocomplete='current-password';password.placeholder='Provider account password';password.setAttribute('aria-label','Z-Library account password');signin.type='submit';disconnect.type='button';login.append(email,password,signin);
 const form=el('form','catalog-search'),input=el('input'),search=el('button','primary','Search account catalog'),cancel=el('button','secondary','Cancel request'),status=el('p','fine'),results=el('div','catalog-results'),next=el('button','secondary','More results');input.type='search';input.maxLength=160;input.placeholder='Title, author or ISBN';input.setAttribute('aria-label','Search Z-Library by title, author or ISBN');search.type='submit';next.type=cancel.type='button';cancel.hidden=next.hidden=true;status.setAttribute('role','status');form.append(input,search,cancel);dialog.append(heading,help,connection,consentLabel,login,disconnect,form,status,results,next);document.body.append(dialog);
 let epoch=0,active=false,connected=false,controller=null,page=1,query='';
 function connectionState(value){connected=!!value;connection.textContent=connected?'Signed in on this device.':'Not signed in on this device.';login.hidden=connected;disconnect.hidden=!connected;search.disabled=!connected;}
 function clear(){epoch++;controller?.abort();controller=null;bridge.cancel();active=false;password.value=email.value=input.value='';consent.checked=false;results.replaceChildren();status.textContent=connection.textContent='';next.hidden=cancel.hidden=true;connectionState(false);signin.disabled=false;if(dialog.open)dialog.close();}
 dialog.addEventListener('close',()=>{if(!dialog.open)clear();});dialog.addEventListener('cancel',e=>{e.preventDefault();clear();});
 function stop(){epoch++;controller?.abort();controller=null;bridge.cancel();active=false;cancel.hidden=true;signin.disabled=false;search.disabled=!connected;next.disabled=false;status.textContent='Request cancelled. Your library was not changed.';}
 cancel.onclick=stop;consent.onchange=()=>{if(!consent.checked)stop();};
 async function run(task,network=true){if(active||!key)return;if(network&&!consent.checked){status.textContent='Allow provider connections first. Nothing has been sent.';consent.focus();return;}const owner=key,id=++epoch;active=true;controller=new AbortController();const signal=controller.signal;signin.disabled=search.disabled=next.disabled=true;cancel.hidden=!network;const fresh=()=>id===epoch&&key===owner&&dialog.open&&(!network||consent.checked);try{return await task(signal,fresh);}catch(e){if(fresh())status.textContent=e.message||'Provider request could not finish.';}finally{if(id===epoch){active=false;controller=null;signin.disabled=false;search.disabled=!connected;next.disabled=false;cancel.hidden=true;}}}
 login.onsubmit=e=>{e.preventDefault();const name=email.value.trim(),secret=password.value;if(!consent.checked){status.textContent='Allow provider connections first. Nothing has been sent.';consent.focus();return;}password.value='';run(async(_signal,fresh)=>{status.textContent='Signing in securely…';const state=await bridge.call({action:'login',email:name,password:secret});if(!fresh())return;connectionState(state.connected);email.value='';status.textContent=connected?'Connected. Your password was not saved.':'Sign-in did not complete.';});};
 disconnect.onclick=()=>run(async(_signal,fresh)=>{await bridge.call({action:'logout'});if(!fresh())return;connectionState(false);results.replaceChildren();next.hidden=true;status.textContent='Provider session removed from this device. Your books remain.';},false);
 async function download(book){return run(async(signal,fresh)=>{if(busy)throw Error('Finish the current save first.');status.textContent='Preparing selected download…';const r=await bridge.call({action:'download',id:book.id,hash:book.hash});if(!fresh())return;if(typeof r?.ticket!=='string'||!/^[a-f0-9-]{36}$/.test(r.ticket))throw Error('Invalid provider transfer.');const response=await fetch('/provider-file?ticket='+encodeURIComponent(r.ticket),{signal,credentials:'omit',cache:'no-store',referrerPolicy:'no-referrer'});if(!response.ok)throw Error('Provider download failed, expired or exceeded32 MB. Your library was not changed.');let bytes;try{bytes=new Uint8Array(await response.arrayBuffer());if(!fresh())return;if(!bytes.length||bytes.length>32*1024*1024)throw Error('Choose a nonempty download under32 MB.');if(busy)throw Error('Another save started; please try the download again.');const file=new File([bytes],'ZLibrary-'+book.id+'.'+book.format.toLowerCase(),{type:book.format==='EPUB'?'application/epub+zip':book.format==='PDF'?'application/pdf':'text/plain'});clear();openUpload([file]);q('book-title').value=book.title;q('book-author').value=book.author;await upload({preventDefault(){}});}finally{bytes?.fill(0);}});}
 function find(number){return run(async(_signal,fresh)=>{status.textContent='Searching your provider catalog…';const r=await bridge.call({action:'search',query,page:number});if(!fresh())return;results.replaceChildren();page=number;for(const item of (Array.isArray(r.books)?r.books:[]).slice(0,20)){if(!['PDF','EPUB','TXT'].includes(item.format))continue;const row=el('article','catalog-result'),button=el('button','secondary','Download to library');button.type='button';button.onclick=()=>download(item);row.append(el('h3','',item.title),el('p','fine',item.author),el('p','fine',[item.format,item.language,item.year,item.size].filter(Boolean).join(' · ')),button);results.append(row);}next.hidden=!r.more;status.textContent=results.children.length?'Showing '+results.children.length+' supported titles. Downloads are limited to32 MB.':'No supported PDF, EPUB or TXT titles on this results page.';});}
 form.onsubmit=e=>{e.preventDefault();query=input.value.trim();if(query)find(1);};next.onclick=()=>find(page+1);
 const open=el('button','nav-item','Z-Library account');open.id='zlibrary-open';open.type='button';open.onclick=()=>{if(!key)return;dialog.showModal();run(async(_signal,fresh)=>{status.textContent='Checking local sign-in…';const state=await bridge.call({action:'status'});if(!fresh())return;connectionState(state.connected);status.textContent=state.connected?'Existing protected sign-in is ready.':'Sign in here; your password will not be stored.';},false);};q('reading-filter').after(open);connectionState(false);
 return {clear};
})();
